// Reuse the responsive component rules for the explicit /mobile entry point.
// This makes mobile layout independent of a browser's "desktop website" width.
import { readFileSync, writeFileSync } from "node:fs";
const css = readFileSync(
  new URL("../styles/globals.css", import.meta.url),
  "utf8",
);
const media = /@media\s*\(max-width:\s*(1200|1023|767|390)px\)\s*\{/g;
let output =
  "/* Generated by scripts/generate-mobile-layout.mjs. Do not edit directly. */\n.mobile-layout { width:100%; max-width:480px; margin-inline:auto; }\n";
for (const match of css.matchAll(media)) {
  const start = match.index + match[0].length;
  let depth = 1,
    end = start;
  while (end < css.length && depth) {
    if (css[end] === "{") depth++;
    if (css[end] === "}") depth--;
    end++;
  }
  if (depth) throw new Error("Unclosed responsive CSS");
  const block = css.slice(start, end - 1);
  if (block.includes("@"))
    throw new Error("Nested responsive at-rule must be handled explicitly");
  output +=
    block.replace(
      /(^|})\s*([^{}]+)\{/g,
      (_, boundary, selector) =>
        `${boundary}\n${selector
          .trim()
          .split(",")
          .map((s) => ".mobile-layout " + s.trim())
          .join(", ")} {`,
    ) + "\n";
}
output +=
  "\n.mobile-layout .modal, .mobile-layout .modal.wide { width:min(464px, calc(100% - 16px)); }\n.mobile-layout .mobile-bottom-nav { width:min(480px, 100%); left:50%; right:auto; transform:translateX(-50%); }\n";
writeFileSync(new URL("../styles/mobile-layout.css", import.meta.url), output);
